// Men's Social — Step 16: Man and Me locked for guests (preview + Google), compact featured card, cleaner tab headers, card rows inside the page margins.
// Everything comes from his real activity on this phone.
// Run from the project folder:  node setup-step-16.mjs
import { mkdirSync, writeFileSync, existsSync, rmSync } from "node:fs";
import { dirname } from "node:path";

if (!existsSync("package.json") || !existsSync("src/components/TabPager.tsx")) {
  console.error("Run this inside the Men-s-Social-True folder, after Step 13.");
  process.exit(1);
}
for (const path of [".next", "setup-step-15.mjs", "src/components/account/SaveProgressCard.tsx"]) {
  if (existsSync(path)) { rmSync(path, { recursive: true, force: true }); console.log("  removed", path); }
}

const files = {
  "src/components/account/LockedTab.tsx": "\"use client\";\n\n// What a guest sees on Man and Me: a soft, blurred look at what's inside, and a quick way to sign up.\n// These tabs hold his personal health records, so they need an account — they're private to him.\n\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { Droplet, Flame, Lock, Moon, ShieldCheck, Smile, Sparkles, Trophy } from \"lucide-react\";\nimport { account, AUTH_METHODS } from \"@/lib/account/useAccount\";\nimport { useToast } from \"@/components/motion/Toast\";\n\nconst COPY = {\n  man: {\n    title: \"Your daily wellness, in one place\",\n    text: \"Track your water, sleep and mood, do small daily activities, and earn points and badges. Private to you.\",\n    points: [\n      { Icon: Droplet, text: \"Water and sleep tracking with simple goals\" },\n      { Icon: Smile, text: \"A 10-second daily check-in on energy and mood\" },\n      { Icon: Flame, text: \"Daily activities, points and a forgiving streak\" },\n    ],\n  },\n  me: {\n    title: \"Your progress and settings\",\n    text: \"See your level, badges and goals, and control your privacy and data. Private to you.\",\n    points: [\n      { Icon: Trophy, text: \"Levels and 9 badges to earn\" },\n      { Icon: Sparkles, text: \"Your goals and the topics you follow\" },\n      { Icon: ShieldCheck, text: \"Download or delete your data any time\" },\n    ],\n  },\n};\n\nexport default function LockedTab({ tab }: { tab: \"man\" | \"me\" }) {\n  const c = COPY[tab];\n  const next = tab === \"man\" ? \"/man\" : \"/me\";\n  const showToast = useToast();\n  const [busy, setBusy] = useState(false);\n\n  return (\n    <div className=\"space-y-5\">\n      <h1 className=\"sr-only\">{tab === \"man\" ? \"Man\" : \"Me\"}</h1>\n\n      {/* Blurred example of the real tab */}\n      <div className=\"relative overflow-hidden rounded-[28px]\" aria-hidden>\n        <div className=\"pointer-events-none select-none space-y-3 blur-[5px]\">\n          {tab === \"man\" ? <ManPreview /> : <MePreview />}\n        </div>\n        <div className=\"absolute inset-0 flex items-center justify-center bg-gradient-to-b from-bg/10 via-bg/40 to-bg\">\n          <span className=\"glass-bar flex h-14 w-14 items-center justify-center rounded-full text-forest-deep\">\n            <Lock size={22} />\n          </span>\n        </div>\n      </div>\n\n      <div className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n        <h2 className=\"text-xl font-bold leading-snug\">{c.title}</h2>\n        <p className=\"mt-1 text-sm text-ink-soft\">{c.text}</p>\n        <ul className=\"mt-4 space-y-2.5\">\n          {c.points.map(({ Icon, text }) => (\n            <li key={text} className=\"flex items-center gap-3 text-sm\">\n              <span className=\"flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-mint text-forest\">\n                <Icon size={16} />\n              </span>\n              {text}\n            </li>\n          ))}\n        </ul>\n\n        <div className=\"mt-5 space-y-2\">\n          {AUTH_METHODS.google && (\n            <button\n              disabled={busy}\n              onClick={async () => {\n                setBusy(true);\n                const r = await account.signInGoogle(next);\n                if (r.error) {\n                  setBusy(false);\n                  showToast(r.error);\n                }\n              }}\n              className=\"flex w-full items-center justify-center gap-3 rounded-full bg-surface py-3.5 text-sm font-semibold ring-1 ring-line transition-transform active:scale-[0.98] disabled:opacity-60\"\n            >\n              <GoogleMark /> Continue with Google\n            </button>\n          )}\n          <Link\n            href={`/account?next=${next}`}\n            className=\"block w-full rounded-full bg-forest py-3.5 text-center text-sm font-semibold text-white transition-transform active:scale-[0.98]\"\n          >\n            Create free account\n          </Link>\n          <Link href={`/account?mode=login&next=${next}`} className=\"block w-full py-2 text-center text-sm font-semibold text-forest\">\n            I have an account · Log in\n          </Link>\n        </div>\n      </div>\n\n      <p className=\"flex items-start gap-2 px-1 text-xs text-ink-soft\">\n        <Lock size={13} className=\"mt-0.5 shrink-0 text-forest\" />\n        Kayani staff can&apos;t read your check-ins, and we never use them for adverts. You can keep reading everything in\n        Social without an account.\n      </p>\n    </div>\n  );\n}\n\n/* Simple look-alikes of the real cards (made-up example values, blurred) */\nfunction ManPreview() {\n  return (\n    <>\n      <div className=\"rounded-3xl bg-forest-deep p-5 text-white\">\n        <p className=\"text-sm text-mint-strong\">Good morning</p>\n        <p className=\"mt-1 text-2xl font-bold\">3 of 6 done today</p>\n        <div className=\"mt-3 h-2.5 rounded-full bg-white/15\">\n          <div className=\"h-full w-1/2 rounded-full bg-mint-strong\" />\n        </div>\n        <p className=\"mt-3 text-xs text-mint\">120 points · Level 2</p>\n      </div>\n      <div className=\"grid grid-cols-2 gap-3\">\n        <div className=\"rounded-3xl bg-surface p-4 ring-1 ring-line\">\n          <Droplet size={18} className=\"text-forest\" />\n          <p className=\"mt-2 text-xl font-bold\">1.5 L</p>\n          <div className=\"mt-2 h-2 rounded-full bg-line\">\n            <div className=\"h-full w-3/5 rounded-full bg-mint-strong\" />\n          </div>\n        </div>\n        <div className=\"rounded-3xl bg-surface p-4 ring-1 ring-line\">\n          <Moon size={18} className=\"text-forest\" />\n          <p className=\"mt-2 text-xl font-bold\">7h 20m</p>\n          <div className=\"mt-2 flex h-8 items-end gap-1\">\n            {[40, 70, 55, 90, 65, 80, 75].map((h, i) => (\n              <span key={i} className=\"flex-1 rounded-sm bg-mint-strong\" style={{ height: `${h}%` }} />\n            ))}\n          </div>\n        </div>\n      </div>\n    </>\n  );\n}\n\nfunction MePreview() {\n  return (\n    <>\n      <div className=\"rounded-3xl bg-forest-deep p-5 text-white\">\n        <div className=\"flex items-center gap-4\">\n          <span className=\"flex h-16 w-16 items-center justify-center rounded-full border-[6px] border-mint-strong text-xl font-bold\">3</span>\n          <div>\n            <p className=\"text-xl font-bold\">Juma</p>\n            <p className=\"text-xs text-mint\">245 points · 6 days in a row</p>\n          </div>\n        </div>\n      </div>\n      <div className=\"grid grid-cols-3 gap-3 rounded-3xl bg-surface p-4 ring-1 ring-line\">\n        {[\"💧\", \"🌙\", \"🔥\", \"📖\", \"⭐\", \"🧭\"].map((e) => (\n          <span key={e} className=\"flex h-16 items-center justify-center rounded-2xl bg-mint text-2xl\">\n            {e}\n          </span>\n        ))}\n      </div>\n    </>\n  );\n}\n\nfunction GoogleMark() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 48 48\" aria-hidden>\n      <path fill=\"#FFC107\" d=\"M43.6 20.5H42V20H24v8h11.3C33.7 32.7 29.2 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.4-.4-3.5z\" />\n      <path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\" />\n      <path fill=\"#4CAF50\" d=\"M24 44c5.2 0 9.9-2 13.4-5.2l-6.2-5.2C29.2 35.1 26.7 36 24 36c-5.2 0-9.6-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\" />\n      <path fill=\"#1976D2\" d=\"M43.6 20.5H42V20H24v8h11.3c-.8 2.2-2.2 4.2-4.1 5.6l6.2 5.2C37 39.2 44 34 44 24c0-1.3-.1-2.4-.4-3.5z\" />\n    </svg>\n  );\n}\n",
  "src/app/(app)/account/page.tsx": "\"use client\";\n\nimport { Suspense, useState } from \"react\";\nimport Link from \"next/link\";\nimport { useRouter, useSearchParams } from \"next/navigation\";\nimport { ArrowLeft, Eye, EyeOff, Loader2, Lock, Mail, Smartphone } from \"lucide-react\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { account, AUTH_METHODS, useAccount } from \"@/lib/account/useAccount\";\n\ntype Mode = \"signup\" | \"login\" | \"reset\";\n\nexport default function AccountPage() {\n  return (\n    <Suspense>\n      <AccountInner />\n    </Suspense>\n  );\n}\n\nfunction AccountInner() {\n  const router = useRouter();\n  const params = useSearchParams();\n  const showToast = useToast();\n  const acc = useAccount();\n  const [mode, setMode] = useState<Mode>(params.get(\"mode\") === \"login\" ? \"login\" : \"signup\");\n  const [phoneOpen, setPhoneOpen] = useState(false);\n\n  // Where to go after signing in: ?next=/man from the welcome screen, otherwise Me\n  const next = params.get(\"next\");\n  const afterSignIn = next && next.startsWith(\"/\") && !next.startsWith(\"//\") ? next : \"/me\";\n  const done = (msg: string) => {\n    showToast(msg);\n    router.push(afterSignIn);\n  };\n\n  if (acc.status === \"signedIn\") {\n    return (\n      <Shell>\n        <div className=\"rounded-3xl bg-surface p-6 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">You&apos;re signed in</p>\n          <Link href={afterSignIn} className=\"mt-4 inline-block rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Continue\n          </Link>\n        </div>\n      </Shell>\n    );\n  }\n  if (acc.status === \"unavailable\") {\n    return (\n      <Shell>\n        <p className=\"rounded-3xl bg-surface p-6 text-sm text-ink-soft ring-1 ring-line\">Accounts aren&apos;t switched on yet. You can keep using the app as a guest.</p>\n      </Shell>\n    );\n  }\n\n  return (\n    <Shell>\n      <div>\n        <h1 className=\"text-2xl font-bold\">{mode === \"login\" ? \"Welcome back\" : mode === \"reset\" ? \"Reset your password\" : \"Create your free account\"}</h1>\n        <p className=\"mt-1 text-sm text-ink-soft\">\n          {mode === \"reset\"\n            ? \"We'll email you a link to choose a new password.\"\n            : \"Keep your points, badges and progress safe, even if you change phones. Only you can see your data.\"}\n        </p>\n      </div>\n\n      {mode !== \"reset\" && (\n        <div className=\"inline-flex w-full rounded-full bg-surface p-1 text-sm font-semibold ring-1 ring-line\" role=\"tablist\">\n          {([\"signup\", \"login\"] as const).map((m) => (\n            <button key={m} role=\"tab\" aria-selected={mode === m} onClick={() => setMode(m)} className={`flex-1 rounded-full py-2 ${mode === m ? \"bg-forest-deep text-white\" : \"text-ink-soft\"}`}>\n              {m === \"signup\" ? \"Sign up\" : \"Log in\"}\n            </button>\n          ))}\n        </div>\n      )}\n\n      {mode !== \"reset\" && (\n        <div className=\"space-y-2\">\n          <button\n            onClick={async () => {\n              const r = await account.signInGoogle(afterSignIn);\n              if (r.error) showToast(r.error);\n            }}\n            disabled={!AUTH_METHODS.google}\n            className=\"flex w-full items-center justify-center gap-3 rounded-full bg-surface py-3.5 text-sm font-semibold ring-1 ring-line disabled:opacity-50\"\n          >\n            <GoogleMark /> Continue with Google\n            {!AUTH_METHODS.google && <span className=\"rounded-full bg-bg px-2 py-0.5 text-[10px] text-ink-soft ring-1 ring-line\">Soon</span>}\n          </button>\n          <button\n            onClick={() => setPhoneOpen((o) => !o)}\n            disabled={!AUTH_METHODS.phone}\n            aria-expanded={phoneOpen}\n            className=\"flex w-full items-center justify-center gap-3 rounded-full bg-surface py-3.5 text-sm font-semibold ring-1 ring-line disabled:opacity-50\"\n          >\n            <Smartphone size={18} className=\"text-forest\" /> Continue with phone number\n            {!AUTH_METHODS.phone && <span className=\"rounded-full bg-bg px-2 py-0.5 text-[10px] text-ink-soft ring-1 ring-line\">Soon</span>}\n          </button>\n          {phoneOpen && AUTH_METHODS.phone && <PhoneForm onDone={() => done(\"Signed in · your progress is saved\")} />}\n          <div className=\"flex items-center gap-3 py-2 text-xs text-ink-soft\">\n            <span className=\"h-px flex-1 bg-line\" /> or with email <span className=\"h-px flex-1 bg-line\" />\n          </div>\n        </div>\n      )}\n\n      <EmailForm mode={mode} onMode={setMode} onDone={done} />\n\n      <p className=\"flex items-start gap-2 px-1 text-xs text-ink-soft\">\n        <Lock size={13} className=\"mt-0.5 shrink-0 text-forest\" />\n        Your check-ins and notes are private. Kayani staff can&apos;t read them, and we never use them for adverts.\n      </p>\n    </Shell>\n  );\n}\n\nfunction EmailForm({ mode, onMode, onDone }: { mode: Mode; onMode: (m: Mode) => void; onDone: (msg: string) => void }) {\n  const [email, setEmail] = useState(\"\");\n  const [password, setPassword] = useState(\"\");\n  const [show, setShow] = useState(false);\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [sent, setSent] = useState<string | null>(null);\n\n  async function submit(e: React.FormEvent) {\n    e.preventDefault();\n    setBusy(true);\n    setError(null);\n    if (mode === \"reset\") {\n      const r = await account.resetPassword(email);\n      setBusy(false);\n      if (r.error) return setError(r.error);\n      return setSent(\"If that email has an account, a reset link is on its way. Check your inbox.\");\n    }\n    const r = mode === \"signup\" ? await account.signUpEmail(email, password) : await account.signInEmail(email, password);\n    setBusy(false);\n    if (r.error) return setError(r.error);\n    if (r.needsConfirm) return setSent(\"Almost done. We sent you an email: tap the link in it to finish creating your account.\");\n    onDone(mode === \"signup\" ? \"Account created · your progress is saved\" : \"Welcome back\");\n  }\n\n  if (sent) {\n    return (\n      <div className=\"rounded-3xl bg-mint/60 p-5 text-sm text-forest-deep\">\n        <Mail size={20} className=\"mb-2 text-forest\" />\n        {sent}\n        <button onClick={() => { setSent(null); onMode(\"login\"); }} className=\"mt-3 block font-semibold text-forest\">\n          Back to log in\n        </button>\n      </div>\n    );\n  }\n\n  return (\n    <form onSubmit={submit} className=\"space-y-3\">\n      <label className=\"block\">\n        <span className=\"text-xs font-semibold text-ink-soft\">Email</span>\n        <input type=\"email\" autoComplete=\"email\" required value={email} onChange={(e) => setEmail(e.target.value)} className={input} />\n      </label>\n      {mode !== \"reset\" && (\n        <label className=\"block\">\n          <span className=\"text-xs font-semibold text-ink-soft\">Password</span>\n          <div className=\"relative\">\n            <input\n              type={show ? \"text\" : \"password\"}\n              autoComplete={mode === \"signup\" ? \"new-password\" : \"current-password\"}\n              required\n              minLength={mode === \"signup\" ? 8 : undefined}\n              value={password}\n              onChange={(e) => setPassword(e.target.value)}\n              className={`${input} pr-11`}\n            />\n            <button type=\"button\" onClick={() => setShow((s) => !s)} aria-label={show ? \"Hide password\" : \"Show password\"} className=\"absolute inset-y-0 right-0 mt-1 flex w-11 items-center justify-center text-ink-soft\">\n              {show ? <EyeOff size={16} /> : <Eye size={16} />}\n            </button>\n          </div>\n          {mode === \"signup\" && <span className=\"mt-1 block text-[11px] text-ink-soft\">At least 8 characters.</span>}\n        </label>\n      )}\n      {error && (\n        <p role=\"alert\" className=\"rounded-2xl bg-red-50 px-3 py-2 text-sm text-red-700\">\n          {error}\n        </p>\n      )}\n      <button disabled={busy} className=\"flex w-full items-center justify-center gap-2 rounded-full bg-forest py-3.5 text-sm font-semibold text-white transition-transform active:scale-[0.98] disabled:opacity-60\">\n        {busy && <Loader2 size={16} className=\"animate-spin\" />}\n        {mode === \"signup\" ? \"Create account\" : mode === \"login\" ? \"Log in\" : \"Send reset link\"}\n      </button>\n      <div className=\"flex justify-between text-xs font-semibold text-forest\">\n        {mode === \"login\" && (\n          <button type=\"button\" onClick={() => onMode(\"reset\")}>\n            Forgot password?\n          </button>\n        )}\n        {mode === \"reset\" && (\n          <button type=\"button\" onClick={() => onMode(\"login\")}>\n            Back to log in\n          </button>\n        )}\n      </div>\n    </form>\n  );\n}\n\nfunction PhoneForm({ onDone }: { onDone: () => void }) {\n  const [phone, setPhone] = useState(\"\");\n  const [sentTo, setSentTo] = useState<string | null>(null);\n  const [code, setCode] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  async function send(e: React.FormEvent) {\n    e.preventDefault();\n    setBusy(true);\n    setError(null);\n    const r = await account.sendPhoneCode(phone);\n    setBusy(false);\n    if (r.error) return setError(r.error);\n    setSentTo(r.phone ?? null);\n  }\n  async function verify(e: React.FormEvent) {\n    e.preventDefault();\n    if (!sentTo) return;\n    setBusy(true);\n    setError(null);\n    const r = await account.verifyPhoneCode(sentTo, code);\n    setBusy(false);\n    if (r.error) return setError(r.error);\n    onDone();\n  }\n\n  return (\n    <form onSubmit={sentTo ? verify : send} className=\"space-y-3 rounded-3xl bg-surface p-4 ring-1 ring-line\">\n      {sentTo ? (\n        <label className=\"block\">\n          <span className=\"text-xs font-semibold text-ink-soft\">Code sent by SMS to {sentTo}</span>\n          <input inputMode=\"numeric\" autoComplete=\"one-time-code\" maxLength={6} value={code} onChange={(e) => setCode(e.target.value.replace(/\\D/g, \"\"))} className={`${input} text-center text-lg tracking-[0.5em]`} />\n        </label>\n      ) : (\n        <label className=\"block\">\n          <span className=\"text-xs font-semibold text-ink-soft\">Mobile number</span>\n          <input type=\"tel\" inputMode=\"tel\" autoComplete=\"tel\" placeholder=\"0712 345 678\" value={phone} onChange={(e) => setPhone(e.target.value)} className={input} />\n        </label>\n      )}\n      {error && <p role=\"alert\" className=\"rounded-2xl bg-red-50 px-3 py-2 text-sm text-red-700\">{error}</p>}\n      <button disabled={busy} className=\"flex w-full items-center justify-center gap-2 rounded-full bg-forest py-3 text-sm font-semibold text-white disabled:opacity-60\">\n        {busy && <Loader2 size={16} className=\"animate-spin\" />}\n        {sentTo ? \"Confirm code\" : \"Send me a code\"}\n      </button>\n      {sentTo && (\n        <button type=\"button\" onClick={() => { setSentTo(null); setCode(\"\"); }} className=\"w-full text-xs font-semibold text-forest\">\n          Use a different number\n        </button>\n      )}\n    </form>\n  );\n}\n\nfunction Shell({ children }: { children: React.ReactNode }) {\n  return (\n    <div className=\"stagger space-y-5\">\n      <Link href=\"/me\" className=\"flex items-center gap-1 text-sm text-ink-soft\">\n        <ArrowLeft size={16} /> Me\n      </Link>\n      {children}\n    </div>\n  );\n}\n\nfunction GoogleMark() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 48 48\" aria-hidden>\n      <path fill=\"#FFC107\" d=\"M43.6 20.5H42V20H24v8h11.3C33.7 32.7 29.2 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.4-.4-3.5z\" />\n      <path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\" />\n      <path fill=\"#4CAF50\" d=\"M24 44c5.2 0 9.9-2 13.4-5.2l-6.2-5.2C29.2 35.1 26.7 36 24 36c-5.2 0-9.6-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\" />\n      <path fill=\"#1976D2\" d=\"M43.6 20.5H42V20H24v8h11.3c-.8 2.2-2.2 4.2-4.1 5.6l6.2 5.2C37 39.2 44 34 44 24c0-1.3-.1-2.4-.4-3.5z\" />\n    </svg>\n  );\n}\n\nconst input = \"mt-1 w-full rounded-2xl bg-surface px-4 py-3 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\";\n",
  "src/app/(app)/social/topic/[id]/page.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { useParams } from \"next/navigation\";\nimport { ArrowLeft } from \"lucide-react\";\nimport { ContentRow } from \"@/components/social/ContentCards\";\nimport { useLibrary } from \"@/lib/content/useLibrary\";\nimport { isSectionId, sectionAll, SECTIONS } from \"@/lib/content/select\";\n\nexport default function TopicPage() {\n  const { id } = useParams<{ id: string }>();\n  const valid = isSectionId(id);\n  const library = useLibrary().items;\n  const items = valid ? sectionAll(id, library) : [];\n  const section = SECTIONS.find((s) => s.id === id);\n\n  return (\n    <div className=\"stagger space-y-4\">\n      <Link href=\"/social\" className=\"flex items-center gap-1 text-sm text-ink-soft\">\n        <ArrowLeft size={16} /> Discover\n      </Link>\n\n      {/* Category navigation */}\n      <div className=\"flex gap-2 overflow-x-auto rounded-full pb-1 [scrollbar-width:none]\">\n        {SECTIONS.map((s) => (\n          <Link\n            key={s.id}\n            href={`/social/topic/${s.id}`}\n            aria-current={s.id === id ? \"page\" : undefined}\n            className={`shrink-0 rounded-full px-3.5 py-2 text-xs font-semibold ${\n              s.id === id ? \"bg-forest-deep text-white\" : \"bg-surface text-ink-soft ring-1 ring-line\"\n            }`}\n          >\n            {s.title}\n          </Link>\n        ))}\n      </div>\n\n      {!valid ? (\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">Topic not found</p>\n          <Link href=\"/social\" className=\"mt-4 inline-block rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Back to Discover\n          </Link>\n        </div>\n      ) : (\n        <>\n          <div>\n            <h1 className=\"text-2xl font-bold leading-tight\">{section?.title}</h1>\n            <p className=\"mt-1 text-sm text-ink-soft\">\n              {items.length} {items.length === 1 ? \"item\" : \"items\"}\n              {section?.blurb ? ` · ${section.blurb}` : \"\"}\n            </p>\n          </div>\n          {items.length === 0 ? (\n            <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n              <p className=\"font-semibold\">Nothing here yet</p>\n              <p className=\"mt-1 text-sm text-ink-soft\">New content for this topic is on the way.</p>\n            </div>\n          ) : (\n            <div className=\"space-y-3\">\n              {items.map((c) => (\n                <ContentRow key={c.id} item={c} />\n              ))}\n            </div>\n          )}\n        </>\n      )}\n    </div>\n  );\n}\n",
  "src/components/TabPager.tsx": "\"use client\";\n\n// The three main tabs side by side in one sliding strip, like a phone app.\n// - Swiping uses the phone's own scrolling (momentum + snap), so the page moves exactly with the finger\n//   and the next tab slides in beside it.\n// - All three tabs stay open in the background: no reloads, and each keeps its scroll position.\n// - The address (/social, /man, /me) follows the tab you land on.\n// - Other pages (an article, sign-up…) open on top of the strip and slide in from the right.\n\nimport { Component, useCallback, useEffect, useLayoutEffect, useRef, useState } from \"react\";\nimport { usePathname, useRouter } from \"next/navigation\";\nimport SocialTab from \"@/components/tabs/SocialTab\";\nimport ManTab from \"@/components/tabs/ManTab\";\nimport MeTab from \"@/components/tabs/MeTab\";\nimport { bubbleShape, isTabRoot, TAB_PATHS, tabFor } from \"@/lib/tabs\";\nimport LockedTab from \"@/components/account/LockedTab\";\nimport { useAccount } from \"@/lib/account/useAccount\";\n\nconst PANELS = [SocialTab, ManTab, MeTab];\n\n/** Tells the glass bubble in the tab bar where the strip is (0 = Social … 2 = Me). */\nfunction setBubble(position: number) {\n  const { x, stretch } = bubbleShape(position);\n  const root = document.documentElement.style;\n  root.setProperty(\"--tab-pos\", String(x));\n  root.setProperty(\"--tab-stretch\", String(stretch));\n}\n\nexport default function TabPager({ children }: { children: React.ReactNode }) {\n  const pathname = usePathname();\n  const router = useRouter();\n  const strip = useRef<HTMLDivElement>(null);\n  const onRoot = isTabRoot(pathname);\n  const tab = tabFor(pathname);\n  const [placed, setPlaced] = useState(false);\n  const settleTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const frame = useRef(0);\n  // Man and Me hold his private records: guests see a locked preview instead\n  const acc = useAccount();\n  const locked = acc.status === \"guest\";\n\n  // Put the strip on the right tab: instantly on first load, smoothly when a tab is tapped\n  useLayoutEffect(() => {\n    const el = strip.current;\n    if (!el || tab < 0) return;\n    const target = tab * el.clientWidth;\n    if (Math.abs(el.scrollLeft - target) > 1) {\n      el.scrollTo({ left: target, behavior: placed ? \"smooth\" : \"instant\" });\n    }\n    if (!placed) {\n      setBubble(tab);\n      setPlaced(true);\n    }\n  }, [tab, placed]);\n\n  // Inside an article etc., the bubble rests on that page's tab\n  useEffect(() => {\n    if (!onRoot && tab >= 0) setBubble(tab);\n  }, [onRoot, tab]);\n\n  // Turning the phone or resizing the window: stay on the same tab\n  useEffect(() => {\n    const onResize = () => {\n      const el = strip.current;\n      if (el && tab >= 0) el.scrollTo({ left: tab * el.clientWidth, behavior: \"instant\" });\n    };\n    window.addEventListener(\"resize\", onResize);\n    return () => window.removeEventListener(\"resize\", onResize);\n  }, [tab]);\n\n  const onScroll = useCallback(() => {\n    const el = strip.current;\n    if (!el) return;\n    cancelAnimationFrame(frame.current);\n    frame.current = requestAnimationFrame(() => setBubble(el.scrollLeft / el.clientWidth));\n    // When the strip comes to rest on another tab, update the address (without adding to Back history)\n    if (settleTimer.current) clearTimeout(settleTimer.current);\n    settleTimer.current = setTimeout(() => {\n      const landed = Math.round(el.scrollLeft / el.clientWidth);\n      if (isTabRoot(window.location.pathname) && TAB_PATHS[landed] !== window.location.pathname) {\n        router.replace(TAB_PATHS[landed], { scroll: false });\n      }\n    }, 90);\n  }, [router]);\n\n  return (\n    <>\n      <div\n        ref={strip}\n        onScroll={onScroll}\n        className={`tab-strip ${placed ? \"opacity-100\" : \"opacity-0\"}`}\n        inert={!onRoot}\n        aria-hidden={!onRoot}\n      >\n        {PANELS.map((Panel, i) => (\n          <section\n            key={TAB_PATHS[i]}\n            id={`tab-panel-${i}`}\n            className=\"tab-panel\"\n            aria-label={[\"Social\", \"Man\", \"Me\"][i]}\n            aria-hidden={onRoot && i !== tab ? true : undefined}\n          >\n            <div className=\"mx-auto max-w-md px-5 pb-32 pt-6\">\n              <PanelBoundary>\n                {i > 0 && acc.status === \"loading\" ? (\n                  <div className=\"h-64 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n                ) : i > 0 && locked ? (\n                  <LockedTab tab={i === 1 ? \"man\" : \"me\"} />\n                ) : (\n                  <Panel />\n                )}\n              </PanelBoundary>\n            </div>\n          </section>\n        ))}\n      </div>\n\n      {!onRoot && (\n        <div className=\"overlay-page\" id=\"overlay-page\">\n          <div className=\"mx-auto max-w-md px-5 pb-32 pt-6\">{children}</div>\n        </div>\n      )}\n    </>\n  );\n}\n\n/** If one tab crashes, the other two keep working. */\nclass PanelBoundary extends Component<{ children: React.ReactNode }, { failed: boolean }> {\n  state = { failed: false };\n  static getDerivedStateFromError() {\n    return { failed: true };\n  }\n  render() {\n    if (!this.state.failed) return this.props.children;\n    return (\n      <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n        <p className=\"font-semibold\">Something went wrong here</p>\n        <button onClick={() => location.reload()} className=\"mt-4 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n          Reload\n        </button>\n      </div>\n    );\n  }\n}\n",
  "src/components/account/AccountInvite.tsx": "\"use client\";\n\n// A friendly \"create a free account\" invite at the right moments, never more than once per moment:\n// - first-save: he saved his first guide\n// Only shown to guests. He can always say \"Not now\".\n\nimport { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { ShieldCheck } from \"lucide-react\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useAccount } from \"@/lib/account/useAccount\";\n\nexport type InviteReason = \"first-save\";\nconst EVENT = \"ms-account-invite\";\nconst seenKey = (r: InviteReason) => `ms_invite_${r}`;\n\nconst COPY: Record<InviteReason, { title: string; text: string }> = {\n  \"first-save\": {\n    title: \"Saved for later\",\n    text: \"Create a free account and your saved guides follow you to any phone.\",\n  },\n};\n\n/** Ask for the invite from anywhere. It only appears if he's a guest and hasn't seen it for this reason. */\nexport function inviteToAccount(reason: InviteReason) {\n  try {\n    if (localStorage.getItem(seenKey(reason))) return;\n  } catch {\n    return;\n  }\n  window.dispatchEvent(new CustomEvent(EVENT, { detail: reason }));\n}\n\n/** Mounted once in the app layout. */\nexport default function AccountInviteSheet() {\n  const acc = useAccount();\n  const [reason, setReason] = useState<InviteReason | null>(null);\n\n  useEffect(() => {\n    if (acc.status !== \"guest\") return;\n    const onInvite = (e: Event) => {\n      const r = (e as CustomEvent<InviteReason>).detail;\n      try {\n        localStorage.setItem(seenKey(r), new Date().toISOString());\n      } catch {}\n      // Let the toast for what he just did show first\n      setTimeout(() => setReason(r), 900);\n    };\n    window.addEventListener(EVENT, onInvite);\n    return () => window.removeEventListener(EVENT, onInvite);\n  }, [acc.status]);\n\n  const copy = reason ? COPY[reason] : null;\n  return (\n    <Sheet open={reason !== null} onClose={() => setReason(null)} title={copy?.title ?? \"\"}>\n      <div className=\"flex gap-3\">\n        <ShieldCheck size={20} className=\"mt-0.5 shrink-0 text-forest\" />\n        <p className=\"text-sm text-ink-soft\">{copy?.text}</p>\n      </div>\n      <div className=\"mt-5 space-y-2\">\n        <Link\n          href=\"/account\"\n          onClick={() => setReason(null)}\n          className=\"block w-full rounded-full bg-forest py-3 text-center text-sm font-semibold text-white\"\n        >\n          Create free account\n        </Link>\n        <button onClick={() => setReason(null)} className=\"w-full py-2 text-sm font-semibold text-ink-soft\">\n          Not now\n        </button>\n      </div>\n    </Sheet>\n  );\n}\n",
  "src/components/social/Community.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { PenLine, ShieldCheck, Stethoscope } from \"lucide-react\";\nimport PostCard from \"./PostCard\";\nimport ComposeSheet from \"./ComposeSheet\";\nimport { useCommunity } from \"./useCommunity\";\nimport { COMMUNITY_TOPICS } from \"@/lib/social/community\";\n\nexport function CommunitySkeleton() {\n  return (\n    <div className=\"space-y-3\" aria-busy=\"true\" aria-label=\"Loading\">\n      {[0, 1, 2].map((i) => (\n        <div key={i} className=\"h-36 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      ))}\n    </div>\n  );\n}\n\nexport default function Community() {\n  const c = useCommunity();\n  const [topic, setTopic] = useState<string>(\"all\");\n  const [sort, setSort] = useState<\"new\" | \"active\">(\"active\");\n  const [asking, setAsking] = useState(false);\n\n  if (!c.ready) return <CommunitySkeleton />;\n  const items = c.list(sort, topic);\n\n  return (\n    <div className=\"space-y-4\">\n      {/* Ask */}\n      <button\n        onClick={() => setAsking(true)}\n        className=\"flex w-full items-center gap-3 rounded-3xl bg-forest-deep p-4 text-left text-white transition-transform active:scale-[0.99]\"\n      >\n        <span className=\"flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-white/15\">\n          <PenLine size={18} />\n        </span>\n        <span className=\"flex-1\">\n          <span className=\"block font-semibold\">Ask a question</span>\n          <span className=\"block text-xs text-mint\">Anonymous by default. Men here have been there too.</span>\n        </span>\n      </button>\n\n      {/* Expert Q&A status — honest until verified professionals are onboarded */}\n      <div className=\"flex items-start gap-3 rounded-2xl px-4 py-3 ring-1 ring-line\">\n        <Stethoscope size={18} className=\"mt-0.5 shrink-0 text-forest\" />\n        <p className=\"text-xs text-ink-soft\">\n          <span className=\"font-semibold text-ink\">Expert Q&amp;A is coming.</span> Verified doctors aren&apos;t on the\n          app yet. Questions marked for an expert are queued for when they join. Meanwhile, see{\" \"}\n          <Link href=\"/social/topic/expert\" className=\"font-semibold text-forest underline\">\n            Expert answers\n          </Link>{\" \"}\n          in Discover.\n        </p>\n      </div>\n\n      {/* Topic filter + sort */}\n      <div className=\"flex gap-2 overflow-x-auto rounded-full pb-1 [scrollbar-width:none]\" role=\"tablist\" aria-label=\"Topic\">\n        {[{ id: \"all\", label: \"All\" }, ...COMMUNITY_TOPICS].map((t) => (\n          <button\n            key={t.id}\n            role=\"tab\"\n            aria-selected={topic === t.id}\n            onClick={() => setTopic(t.id)}\n            className={`shrink-0 rounded-full px-3.5 py-2 text-xs font-semibold transition-colors ${\n              topic === t.id ? \"bg-forest-deep text-white\" : \"bg-surface text-ink-soft ring-1 ring-line\"\n            }`}\n          >\n            {t.label}\n          </button>\n        ))}\n      </div>\n      <div className=\"flex items-center justify-between text-xs\">\n        <span className=\"text-ink-soft\">\n          {items.length} {items.length === 1 ? \"conversation\" : \"conversations\"}\n        </span>\n        <div className=\"flex rounded-full bg-surface p-0.5 ring-1 ring-line\">\n          {([\"active\", \"new\"] as const).map((s) => (\n            <button\n              key={s}\n              aria-pressed={sort === s}\n              onClick={() => setSort(s)}\n              className={`rounded-full px-3 py-1 font-semibold ${sort === s ? \"bg-forest text-white\" : \"text-ink-soft\"}`}\n            >\n              {s === \"active\" ? \"Most active\" : \"Newest\"}\n            </button>\n          ))}\n        </div>\n      </div>\n\n      {/* Feed */}\n      {items.length === 0 ? (\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">No conversations here yet</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">Be the first to ask. Anonymous is fine.</p>\n          <button onClick={() => setAsking(true)} className=\"mt-4 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Ask a question\n          </button>\n        </div>\n      ) : (\n        <div className=\"stagger space-y-3\">\n          {items.map(({ post, replyCount }) => (\n            <PostCard key={post.id} post={post} replyCount={replyCount} />\n          ))}\n        </div>\n      )}\n\n      <p className=\"flex items-start justify-center gap-1.5 px-2 text-center text-[11px] text-ink-soft\">\n        <ShieldCheck size={12} className=\"mt-px shrink-0\" />\n        Be kind. No selling, phone numbers or links. Posts marked &quot;Sample&quot; are examples. Until the server is\n        connected, your posts are saved on this phone only.\n      </p>\n\n      <ComposeSheet open={asking} onClose={() => setAsking(false)} />\n    </div>\n  );\n}\n",
  "src/components/social/ContentCards.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { ChevronRight } from \"lucide-react\";\nimport Cover from \"./Cover\";\nimport BookmarkButton from \"./BookmarkButton\";\nimport { KIND_LABEL } from \"@/lib/content/select\";\nimport type { ContentItem } from \"@/lib/content/types\";\n\nexport const contentHref = (id: string) => `/social/c/${id}`;\n\n/** Small card for horizontal rows on Discover. */\nexport function ContentCard({ item }: { item: ContentItem }) {\n  return (\n    <Link\n      href={contentHref(item.id)}\n      className=\"block w-44 shrink-0 snap-start overflow-hidden rounded-3xl bg-surface ring-1 ring-line transition-transform active:scale-[0.98]\"\n    >\n      <Cover item={item} className=\"h-24 w-full\" />\n      <div className=\"p-3\">\n        <p className=\"text-[10px] font-semibold uppercase tracking-wide text-forest\">\n          {KIND_LABEL[item.kind]} · {item.minutes} min\n        </p>\n        <p className=\"mt-1 line-clamp-3 text-[13px] font-semibold leading-snug\">{item.title}</p>\n      </div>\n    </Link>\n  );\n}\n\n/** Row for lists: search results, saved, topic pages. */\nexport function ContentRow({ item }: { item: ContentItem }) {\n  return (\n    <Link href={contentHref(item.id)} className=\"flex items-center gap-3 rounded-3xl bg-surface p-3 ring-1 ring-line\">\n      <Cover item={item} className=\"h-16 w-16 shrink-0 rounded-2xl\" showPlay={false} />\n      <div className=\"min-w-0 flex-1\">\n        <p className=\"text-[10px] font-semibold uppercase tracking-wide text-forest\">\n          {KIND_LABEL[item.kind]} · {item.minutes} min\n        </p>\n        <p className=\"line-clamp-2 text-sm font-semibold leading-snug\">{item.title}</p>\n      </div>\n      <BookmarkButton contentId={item.id} variant=\"plain\" />\n    </Link>\n  );\n}\n\n/** A Discover section: title, \"See all\", and a horizontal row of cards. */\nexport function SectionRow({\n  id,\n  title,\n  blurb,\n  items,\n}: {\n  id: string;\n  title: string;\n  blurb?: string;\n  items: ContentItem[];\n}) {\n  if (items.length === 0) return null;\n  return (\n    <section aria-labelledby={`sec-${id}`}>\n      <div className=\"flex items-end justify-between gap-3\">\n        <div>\n          <h2 id={`sec-${id}`} className=\"text-base font-bold\">\n            {title}\n          </h2>\n          {blurb && <p className=\"text-xs text-ink-soft\">{blurb}</p>}\n        </div>\n        <Link href={`/social/topic/${id}`} className=\"flex shrink-0 items-center text-xs font-semibold text-forest\">\n          See all <ChevronRight size={14} />\n        </Link>\n      </div>\n      <div className=\"mt-3 flex snap-x gap-3 overflow-x-auto rounded-3xl pb-1 [scrollbar-width:none]\">\n        {items.map((c) => (\n          <ContentCard key={c.id} item={c} />\n        ))}\n      </div>\n    </section>\n  );\n}\n",
  "src/components/social/FeaturedCard.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { ArrowRight } from \"lucide-react\";\nimport Cover from \"./Cover\";\nimport BookmarkButton from \"./BookmarkButton\";\nimport { contentHref } from \"./ContentCards\";\nimport { CTA_LABEL, KIND_LABEL } from \"@/lib/content/select\";\nimport { TOPICS } from \"@/lib/content/library\";\nimport type { ContentItem } from \"@/lib/content/types\";\n\n/** The one featured piece at the top of Discover — compact, so the sections below show on the first screen. */\nexport default function FeaturedCard({ item, reason }: { item: ContentItem; reason: string }) {\n  const topic = TOPICS.find((t) => t.id === item.topic)?.short;\n  return (\n    <article className=\"overflow-hidden rounded-[28px] bg-forest-deep text-white\">\n      <Link href={contentHref(item.id)} className=\"relative block\" aria-label={item.title}>\n        <Cover item={item} className=\"aspect-[2/1] w-full\" />\n        <div className=\"absolute left-4 top-4 flex gap-2\">\n          <span className=\"rounded-full bg-white/90 px-3 py-1 text-[11px] font-bold text-forest-deep\">Featured</span>\n          {item.fixture && (\n            <span className=\"rounded-full bg-black/35 px-3 py-1 text-[11px] font-semibold text-white backdrop-blur\">Sample</span>\n          )}\n        </div>\n      </Link>\n\n      <div className=\"p-4\">\n        <p className=\"text-[11px] font-semibold uppercase tracking-wider text-mint-strong\">\n          {topic} · {KIND_LABEL[item.kind]} · {item.minutes} min\n        </p>\n        <Link href={contentHref(item.id)}>\n          <h2 className=\"mt-1.5 text-[20px] font-bold leading-snug\">{item.title}</h2>\n        </Link>\n        <p className=\"mt-1 line-clamp-2 text-sm text-mint\">{item.summary}</p>\n\n        <div className=\"mt-3 flex items-center gap-2\">\n          <Link\n            href={contentHref(item.id)}\n            className=\"flex flex-1 items-center justify-center gap-2 rounded-full bg-white py-2.5 text-sm font-bold text-forest-deep transition-transform active:scale-[0.98]\"\n          >\n            {CTA_LABEL[item.kind]} <ArrowRight size={16} />\n          </Link>\n          <BookmarkButton contentId={item.id} variant=\"dark\" />\n        </div>\n        <p className=\"mt-2 line-clamp-1 text-[11px] text-mint/70\">{reason}</p>\n      </div>\n    </article>\n  );\n}\n",
  "src/components/tabs/ManTab.tsx": "\"use client\";\n\n// \"Man\": Home and Progress in one place.\n// Top: what to do today (all interactive right here). Bottom: his trends.\n\nimport TopBar from \"@/components/feed/TopBar\";\nimport ActivitiesCard from \"@/components/feed/ActivitiesCard\";\nimport TrendsSection from \"@/components/feed/TrendsSection\";\nimport { EndCard, LessonCard, ReminderCard, TipCard, TodayCard } from \"@/components/feed/FeedCards\";\nimport { useHomeFeed } from \"@/components/feed/useHomeFeed\";\nimport CheckInCard from \"@/components/progress/CheckInCard\";\nimport HydrationCard from \"@/components/progress/HydrationCard\";\nimport SleepCard from \"@/components/progress/SleepCard\";\n\nexport default function ManTab() {\n  const f = useHomeFeed();\n\n  if (!f.ready) {\n    return (\n      <div className=\"space-y-4\">\n        <TopBar />\n        <div className=\"h-40 animate-pulse rounded-3xl bg-forest-deep/20\" />\n        <div className=\"h-64 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"stagger space-y-4\">\n      <TopBar />\n      <TodayCard f={f} />\n      {f.allClosed ? <EndCard /> : <ReminderCard f={f} />}\n\n      <div id=\"checkin\" className=\"scroll-mt-4\">\n        <CheckInCard period={1} />\n      </div>\n      <div id=\"sleep\" className=\"scroll-mt-4\">\n        <SleepCard period={1} />\n      </div>\n      <div id=\"water\" className=\"scroll-mt-4\">\n        <HydrationCard period={1} />\n      </div>\n      <ActivitiesCard f={f} />\n\n      <LessonCard f={f} />\n      <TipCard f={f} />\n\n      <div className=\"pt-4\">\n        <TrendsSection />\n      </div>\n\n      <p className=\"px-2 pt-2 text-center text-[11px] text-ink-soft\">Saved privately to your account.</p>\n    </div>\n  );\n}\n",
  "src/components/tabs/MeTab.tsx": "\"use client\";\n\n// \"Me\": who he is in the app, what he's earned, his goals, settings and privacy controls.\n// Everything here comes from his real activity on this phone.\n\nimport ProfileHero from \"@/components/me/ProfileHero\";\nimport BadgesSection from \"@/components/me/BadgesSection\";\nimport { GoalsCard, PrivacyCard, SettingsCard } from \"@/components/me/SettingsSections\";\nimport { useHomeFeed } from \"@/components/feed/useHomeFeed\";\nimport { useFeed } from \"@/lib/feed/store\";\nimport { computeBadges, firstActiveDay } from \"@/lib/me/badges\";\nimport { useLang } from \"@/lib/me/lang\";\nimport { goalFor, useProgress } from \"@/lib/progress/store\";\nimport { useSocial } from \"@/lib/social/store\";\nimport { useAccount } from \"@/lib/account/useAccount\";\n\nexport default function MeTab() {\n  const f = useHomeFeed();\n  const feed = useFeed();\n  const progress = useProgress();\n  const social = useSocial();\n  const lang = useLang();\n  const acc = useAccount();\n\n  if (!f.ready || !social.ready) {\n    return (\n      <div className=\"space-y-4\" aria-busy=\"true\" aria-label=\"Loading\">\n        <div className=\"h-52 animate-pulse rounded-[28px] bg-forest-deep/15\" />\n        <div className=\"h-64 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      </div>\n    );\n  }\n\n  const badges = computeBadges({\n    records: progress.records,\n    goals: progress.goals,\n    feed,\n    points: f.points,\n    pointDays: f.pointDays,\n    bookmarks: Object.keys(social.bookmarks).length,\n    posts: social.posts.length,\n    replies: social.replies.length,\n  });\n\n  return (\n    <div className=\"stagger space-y-4\">\n      <h1 className=\"sr-only\">Me</h1>\n      <ProfileHero\n        nickname={social.nickname}\n        points={f.points}\n        level={f.level}\n        streak={f.streak}\n        since={firstActiveDay({ records: progress.records, feed })}\n      />\n      <BadgesSection badges={badges} />\n      <GoalsCard\n        water={goalFor(progress.goals, \"water\")?.target ?? null}\n        sleep={goalFor(progress.goals, \"sleep\")?.target ?? null}\n        interests={social.interests}\n      />\n      <SettingsCard lang={lang} discreet={feed.settings.discreet} />\n      <PrivacyCard acc={acc} />\n      <p className=\"pb-2 text-center text-[11px] text-ink-soft\">Kayani Men&apos;s Social · test version</p>\n    </div>\n  );\n}\n",
  "src/components/tabs/SocialTab.tsx": "\"use client\";\n\nimport { Suspense, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { useSearchParams } from \"next/navigation\";\nimport { Bookmark, Search } from \"lucide-react\";\nimport Discover, { DiscoverSkeleton } from \"@/components/social/Discover\";\nimport Community from \"@/components/social/Community\";\nimport SearchPanel from \"@/components/social/SearchPanel\";\n\ntype Tab = \"discover\" | \"community\";\n\nfunction SocialInner() {\n  // Opens on Community when the address says ?tab=community (e.g. a shared link); after that it's\n  // remembered while he moves between the main tabs, because this tab stays open in the background.\n  const params = useSearchParams();\n  const [tab, setTab] = useState<Tab>(params.get(\"tab\") === \"community\" ? \"community\" : \"discover\");\n  const [searching, setSearching] = useState(false);\n  // Coming back from a Community post (link to /social?tab=community) switches to Community\n  const wanted = params.get(\"tab\");\n  useEffect(() => {\n    if (wanted === \"community\") setTab(\"community\");\n  }, [wanted]);\n\n  return (\n    <div className=\"space-y-5\">\n      {/* One row: Discover / Community on the left, Search and Saved on the right */}\n      <header className=\"flex items-center justify-between gap-2\">\n        <h1 className=\"sr-only\">Social</h1>\n        <div className=\"inline-flex rounded-full bg-surface p-1 ring-1 ring-line\" role=\"tablist\" aria-label=\"Social sections\">\n          {([\"discover\", \"community\"] as const).map((t) => (\n            <button\n              key={t}\n              role=\"tab\"\n              id={`tab-${t}`}\n              aria-selected={tab === t}\n              aria-controls=\"social-panel\"\n              onClick={() => setTab(t)}\n              className={`rounded-full px-4 py-2 text-sm font-semibold transition-colors ${\n                tab === t ? \"bg-forest-deep text-white\" : \"text-ink-soft\"\n              }`}\n            >\n              {t === \"discover\" ? \"Discover\" : \"Community\"}\n            </button>\n          ))}\n        </div>\n        <div className=\"flex shrink-0 gap-2\">\n          <button\n            aria-label=\"Search\"\n            aria-pressed={searching}\n            onClick={() => setSearching((s) => !s)}\n            className=\"flex h-10 w-10 items-center justify-center rounded-full bg-surface ring-1 ring-line transition-transform active:scale-95\"\n          >\n            <Search size={18} />\n          </button>\n          <Link\n            href=\"/social/saved\"\n            aria-label=\"Saved\"\n            className=\"flex h-10 w-10 items-center justify-center rounded-full bg-surface ring-1 ring-line transition-transform active:scale-95\"\n          >\n            <Bookmark size={18} />\n          </Link>\n        </div>\n      </header>\n\n      <div id=\"social-panel\" role=\"tabpanel\" aria-labelledby={`tab-${tab}`} key={`${tab}-${searching}`} className=\"page-enter\">\n        {searching ? (\n          <SearchPanel tab={tab} onClose={() => setSearching(false)} />\n        ) : tab === \"discover\" ? (\n          <Discover />\n        ) : (\n          <Community />\n        )}\n      </div>\n    </div>\n  );\n}\n\nexport default function SocialTab() {\n  return (\n    <Suspense fallback={<DiscoverSkeleton />}>\n      <SocialInner />\n    </Suspense>\n  );\n}\n",
  "src/lib/account/useAccount.ts": "\"use client\";\n\n// Is a man signed in to his own account? Sign up / log in with email, Google or phone.\n\nimport { useEffect, useState } from \"react\";\nimport type { User } from \"@supabase/supabase-js\";\nimport { getSupabase, supabaseConfigured } from \"../supabase/client\";\nimport { normalizeTzPhone } from \"./merge\";\n\nexport type AccountState =\n  | { status: \"loading\" }\n  | { status: \"unavailable\" } // Supabase not set up: guest only\n  | { status: \"guest\" }\n  | { status: \"signedIn\"; user: User };\n\n/** Which sign-in methods are switched on (set in .env.local / Vercel once each is set up in Supabase). */\nexport const AUTH_METHODS = {\n  email: true,\n  google: process.env.NEXT_PUBLIC_AUTH_GOOGLE === \"on\",\n  phone: process.env.NEXT_PUBLIC_AUTH_PHONE === \"on\",\n};\n\nexport function useAccount(): AccountState {\n  const [state, setState] = useState<AccountState>(supabaseConfigured ? { status: \"loading\" } : { status: \"unavailable\" });\n  useEffect(() => {\n    const sb = getSupabase();\n    if (!sb) return;\n    sb.auth.getSession().then(({ data }) =>\n      setState(data.session?.user ? { status: \"signedIn\", user: data.session.user } : { status: \"guest\" }),\n    );\n    const { data } = sb.auth.onAuthStateChange((_e, session) =>\n      setState(session?.user ? { status: \"signedIn\", user: session.user } : { status: \"guest\" }),\n    );\n    return () => data.subscription.unsubscribe();\n  }, []);\n  return state;\n}\n\n/** How we show who he is: email, phone, or \"Google account\". */\nexport function accountLabel(user: User): string {\n  return user.email || (user.phone ? `+${user.phone.replace(/^\\+/, \"\")}` : \"Your account\");\n}\n\nconst friendly = (message: string): string => {\n  const m = message.toLowerCase();\n  if (m.includes(\"already registered\") || m.includes(\"already been registered\")) return \"This email already has an account. Log in instead.\";\n  if (m.includes(\"invalid login\")) return \"Wrong email or password.\";\n  if (m.includes(\"email not confirmed\")) return \"Please confirm your email first. Check your inbox.\";\n  if (m.includes(\"password should be\") || m.includes(\"weak\")) return \"Choose a stronger password: at least 8 characters.\";\n  if (m.includes(\"rate limit\") || m.includes(\"too many\")) return \"Too many tries. Please wait a few minutes and try again.\";\n  if (m.includes(\"token has expired\") || m.includes(\"invalid otp\") || m.includes(\"otp\")) return \"That code is wrong or expired. Ask for a new one.\";\n  if (m.includes(\"fetch\") || m.includes(\"network\")) return \"Can't connect. Check your internet and try again.\";\n  if (m.includes(\"provider is not enabled\") || m.includes(\"unsupported provider\")) return \"This sign-in option isn't switched on yet.\";\n  return message;\n};\n\ntype Result = { error: string | null; needsConfirm?: boolean };\n\nexport const account = {\n  async signUpEmail(email: string, password: string): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    if (password.length < 8) return { error: \"Use at least 8 characters for your password.\" };\n    const { data, error } = await sb.auth.signUp({ email: email.trim(), password, options: { emailRedirectTo: `${location.origin}/me` } });\n    if (error) return { error: friendly(error.message) };\n    // Supabase hides \"already registered\" by returning a user with no identities\n    if (data.user && data.user.identities?.length === 0) return { error: friendly(\"already registered\") };\n    return { error: null, needsConfirm: !data.session };\n  },\n\n  async signInEmail(email: string, password: string): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const { error } = await sb.auth.signInWithPassword({ email: email.trim(), password });\n    return { error: error ? friendly(error.message) : null };\n  },\n\n  async resetPassword(email: string): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const { error } = await sb.auth.resetPasswordForEmail(email.trim(), { redirectTo: `${location.origin}/account/new-password` });\n    return { error: error ? friendly(error.message) : null };\n  },\n\n  async setNewPassword(password: string): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    if (password.length < 8) return { error: \"Use at least 8 characters for your password.\" };\n    const { error } = await sb.auth.updateUser({ password });\n    return { error: error ? friendly(error.message) : null };\n  },\n\n  /** Google sends him back to `next` (the tab or page he started from). */\n  async signInGoogle(next = \"/me\"): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const safe = next.startsWith(\"/\") && !next.startsWith(\"//\") ? next : \"/me\";\n    const { error } = await sb.auth.signInWithOAuth({ provider: \"google\", options: { redirectTo: `${location.origin}${safe}` } });\n    return { error: error ? friendly(error.message) : null };\n  },\n\n  async sendPhoneCode(phoneInput: string): Promise<Result & { phone?: string }> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const phone = normalizeTzPhone(phoneInput);\n    if (!phone) return { error: \"Enter a Tanzanian mobile number, e.g. 0712 345 678.\" };\n    const { error } = await sb.auth.signInWithOtp({ phone });\n    return { error: error ? friendly(error.message) : null, phone };\n  },\n\n  async verifyPhoneCode(phone: string, code: string): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const { error } = await sb.auth.verifyOtp({ phone, token: code.trim(), type: \"sms\" });\n    return { error: error ? friendly(error.message) : null };\n  },\n\n  async signOut() {\n    await getSupabase()?.auth.signOut();\n  },\n\n  async deleteAccount(): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const { error } = await sb.rpc(\"delete_my_account\");\n    if (error) return { error: friendly(error.message) };\n    await sb.auth.signOut();\n    return { error: null };\n  },\n};\n"
};

for (const [path, content] of Object.entries(files)) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log("  wrote", path);
}
console.log("\nDone: " + Object.keys(files).length + " files. Next: npm test, then npx next dev --turbopack, then open http://localhost:3000");
